## 1. A class

A class bundles related data and behaviour under one name. JavaScript and TypeScript have them,
same as Java or C#.

```ts
class Thing {
  // fields hold values
  // methods do work
}
```

class Greeter {
  language: string;

  constructor(language: string) {
    this.language = language;
  }

  greet(name: string): string {
    return this.language === "en" ? `Hello ${name}` : `Bonjour ${name}`;
  }
}

const en = new Greeter("en");
const fr = new Greeter("fr");

console.log(en.greet("Leela"));
console.log(fr.greet("Leela"));

class Counter {
  count: number;
  readonly label: string;         // readonly: set once in the constructor, never reassigned

  constructor(label: string) {
    console.log(`  constructor ran for "${label}"`);
    this.label = label;
    this.count = 0;
  }

  add(): number {
    this.count = this.count + 1;   // `this.count` — mine, not the other instance's
    return this.count;
  }
}

console.log("creating two counters:");
const a = new Counter("a");
const b = new Counter("b");

a.add(); a.add(); b.add();
console.log(`a.count=${a.count}  b.count=${b.count}`);
// b.label = "changed";        // <- uncomment: readonly, TypeScript refuses

## 3. `export` and `import`

A class in one file is no use to another until it's exported.

```ts
// login-page.ts
export class LoginPage { ... }

// some.spec.ts
import { LoginPage } from "./login-page";
```

`export class` is a **named** export, so the importing file uses the same name in braces. (The
`export default` from Day 1.1 is the other form — one per file, no braces.)

You may also see the older `require("./login-page")` form; the transcript this lesson comes from
uses it. `import` is the modern equivalent and what this repo uses.

// Notebook cells can't use export/import, so here's the shape as text
const helperFile = [
  "// login-page.ts",
  "export class LoginPage {",
  "  constructor(page) { this.page = page; }",
  "}",
].join("\n");

const specFile = [
  "// dashboard.spec.ts",
  'import { LoginPage } from "./login-page";',
  "const loginPage = new LoginPage(page);",
].join("\n");

console.log(helperFile);
console.log("---");
console.log(specFile);

type User = { email: string; password: string };

const LEELA: User = { email: "leela@gmail.com", password: "Leela@123" };
const KATY: User = { email: "katy@gmail.com", password: "Katy@12354" };

class Session {
  // default parameter: called with nothing, it uses LEELA
  signIn(user: User = LEELA): string {
    return `signing in as ${user.email}`;
  }

  // async method: returns a Promise, so callers await it
  async slowSignIn(user: User = LEELA): Promise<string> {
    await new Promise((r) => setTimeout(r, 100));
    return `signed in as ${user.email}`;
  }
}

const s = new Session();
console.log(s.signIn());          // no argument -> the default
console.log(s.signIn(KATY));      // explicit
console.log(await s.slowSignIn(KATY));

import { launch, BASE_URL } from "../_shared/deno-helpers.ts";

const { browser, page } = await launch();

// "Spec 1"
await page.goto(BASE_URL);
await page.getByPlaceholder("Enter Email").fill("leela@gmail.com");
await page.getByPlaceholder("Enter Password").fill("Leela@123");
await page.getByRole("button", { name: "Login" }).click();
await page.waitForURL("**/dashboard");
console.log("spec 1 reached:", page.url().split("/").pop());

// "Spec 2" — same four lines again
await page.getByRole("button", { name: "LogOut" }).click();
await page.waitForURL("**/login");
await page.getByPlaceholder("Enter Email").fill("katy@gmail.com");
await page.getByPlaceholder("Enter Password").fill("Katy@12354");
await page.getByRole("button", { name: "Login" }).click();
await page.waitForURL("**/dashboard");
console.log("spec 2 reached:", page.url().split("/").pop());

