import type { Locator, Page } from "npm:playwright";

class LoginPage {
  readonly page: Page;
  readonly emailBox: Locator;
  readonly passwordBox: Locator;
  readonly loginButton: Locator;
  readonly logoutButton: Locator;

  constructor(page: Page) {
    this.page = page;
    // Built once. One place to edit when the markup changes.
    this.emailBox = page.getByPlaceholder("Enter Email");
    this.passwordBox = page.getByPlaceholder("Enter Password");
    this.loginButton = page.getByRole("button", { name: "Login" });
    this.logoutButton = page.getByRole("button", { name: "LogOut" });
  }

  async open(): Promise<void> {
    await this.page.goto(BASE_URL);
  }

  async signIn(email = "leela@gmail.com", password = "Leela@123"): Promise<void> {
    await this.emailBox.fill(email);
    await this.passwordBox.fill(password);
    await this.loginButton.click();
    await this.page.waitForURL("**/dashboard");
  }

  async signOut(): Promise<void> {
    await this.logoutButton.click();
    await this.page.waitForURL("**/login");
  }
}

// Now the same two journeys read completely differently
const loginPage = new LoginPage(page);

await loginPage.signOut();
await loginPage.open();
await loginPage.signIn();
console.log("as Leela  ->", page.url().split("/").pop());

await loginPage.signOut();
await loginPage.signIn("katy@gmail.com", "Katy@12354");
console.log("as Katy   ->", page.url().split("/").pop());

