import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template
// literal — see Week 4 Day 1.1, concept 2.

await writeProjectFile("week3/generated/day3-login-page.ts", `// Week 3, Day 3 — the common code, in one place.
//
// Note the filename: NOT .spec.ts. This file defines behaviour; it contains no
// test() calls, so the runner never collects it. That distinction matters — a
// helper named *.spec.ts would be run as an empty test file.
//
// Written by a cell in week3/day3_2.ipynb.
import { type Locator, type Page } from "@playwright/test";
import { USERS, type BankUser } from "../../_shared/test-helpers";

/**
 * Everything the login and dashboard screens can do, named once.
 *
 * Locators are built in the constructor and marked \`readonly\`: one place to edit
 * when the markup changes, and a compile error if a method tries to reassign one.
 */
export class LoginPage {
  readonly page: Page;
  readonly emailBox: Locator;
  readonly passwordBox: Locator;
  readonly loginButton: Locator;
  readonly logoutButton: Locator;
  readonly accountBalance: Locator;

  constructor(page: Page) {
    this.page = page;
    // \`this.page\` is the page handed in at construction time — the same instance
    // the test is driving, not a new one.
    this.emailBox = page.getByPlaceholder("Enter Email");
    this.passwordBox = page.getByPlaceholder("Enter Password");
    this.loginButton = page.getByRole("button", { name: "Login" });
    this.logoutButton = page.getByRole("button", { name: "LogOut" });
    this.accountBalance = page.getByText("Account Balance", { exact: true });
  }

  /** Named for what the user is doing, not for the DOM operations involved. */
  async open(): Promise<void> {
    await this.page.goto("/");
  }

  async signIn(user: BankUser = USERS[0]): Promise<void> {
    await this.emailBox.fill(user.email);
    await this.passwordBox.fill(user.password);
    await this.loginButton.click();
    await this.page.waitForURL("**/dashboard");
  }

  async signOut(): Promise<void> {
    await this.logoutButton.click();
    await this.page.waitForURL("**/login");
  }

  /**
   * Opens one of the dashboard tiles. They are \`<p>\` elements, not links, so
   * getByRole("link", ...) finds nothing here — a real quirk of this app.
   */
  async openTile(name: string): Promise<void> {
    await this.page.getByText(name, { exact: true }).click();
  }
}
`);

await writeProjectFile("week3/generated/day3-base-page.spec.ts", `// Week 3, Day 3 — the same journeys, driven through the shared class.
//
// Compare this with day2-hooks.spec.ts: no placeholders, no button names, no URLs
// spelled out. If the login markup changes tomorrow, this file does not.
//
// Written by a cell in week3/day3_2.ipynb. Run it yourself:
//   npx playwright test week3/generated/day3-base-page.spec.ts
import { test, expect } from "@playwright/test";
import { USERS } from "../../_shared/test-helpers";
import { LoginPage } from "./day3-login-page";

test.describe("Using the shared LoginPage", () => {
  // beforeEach, not beforeAll: the \`page\` fixture is a fresh page per test, so
  // each test has to sign in for itself. That is the trade for isolation.
  let loginPage: LoginPage;

  test.beforeEach(async ({ page }) => {
    loginPage = new LoginPage(page);
    await loginPage.open();
    await loginPage.signIn();
  });

  test("Step 1 — signing in lands on the dashboard", async ({ page }) => {
    await expect(page).toHaveURL(/\\/dashboard/);
    // The test asserts. The class only got us here.
    await expect(loginPage.accountBalance).toBeVisible();
  });

  test("Step 2 — a tile opens its own view", async ({ page }) => {
    await loginPage.openTile("Pay Bills");
    await expect(page).toHaveURL(/paymentDashboard/);
  });

  test("Step 3 — signing out returns to the login form", async () => {
    await loginPage.signOut();
    await expect(loginPage.emailBox).toBeVisible();
  });

  test("Step 4 — a different user signs in through the same class", async ({ page }) => {
    await loginPage.signOut();
    await loginPage.signIn(USERS[1]);
    await expect(page).toHaveURL(/\\/dashboard/);
  });
});
`);

await runSpec("week3/generated/day3-base-page.spec.ts");

// The shapes. Nothing runs — this is the direction of travel.
const basePage = `
class BasePage {
  constructor(protected page: Page) {}
  async goto(path: string) { await this.page.goto(path); }
}

class LoginPage extends BasePage {
  readonly emailBox = this.page.getByPlaceholder("Enter Email");
  async signIn(user: BankUser = USERS[0]) { /* ... */ }
}`.trim();

const withFixture = `
// framework/test.ts
export const test = base.extend<{ loginPage: LoginPage }>({
  loginPage: async ({ page }, use) => { await use(new LoginPage(page)); },
});

// any.spec.ts
test("signs in", async ({ loginPage, page }) => {
  await loginPage.open();
  await loginPage.signIn();
  await expect(page).toHaveURL(/dashboard/);
});`.trim();

console.log(basePage);
console.log("\n---\n");
console.log(withFixture);

